-- Restore seletivo pos-fix bug de merge raso (2026-08-14)
-- Fonte: pontual-full-2026-08-14-020001.tar.gz (snapshot PG 02:00 UTC-3)
-- Estrategia: jsonb_deep_merge(backup, atual) => atual VENCE em conflito de escalar,
--             backup preenche APENAS chaves ausentes / sub-objetos que sumiram.
-- SEGURO: nao desfaz edit legitimo feito hoje apos 02:00; so preenche buracos.
-- Pre-req: rodar 014-jsonb-deep-merge.sql ANTES (cria a funcao).

BEGIN;

DROP SCHEMA IF EXISTS backup_restore CASCADE;
CREATE SCHEMA backup_restore;

CREATE TABLE backup_restore.documents (
  id text, collection text, data jsonb, created_at timestamptz, updated_at timestamptz
);
CREATE TABLE backup_restore.veiculos (LIKE public.veiculos INCLUDING DEFAULTS);

-- Carga MOTORISTAS (36 linhas)

-- Carga VEICULOS (82 linhas)

\echo '=== ANTES ==='
SELECT 'motoristas_com_docs' AS k, count(*) AS v FROM public.documents WHERE collection='motoristas' AND jsonb_typeof(data->'documentos')='object' AND data->'documentos' <> '{}'::jsonb;
SELECT 'veiculos_com_extras' AS k, count(*) AS v FROM public.veiculos WHERE extras IS NOT NULL AND extras <> '{}'::jsonb;

-- RESTORE motoristas: preserva atual, backup preenche buracos e sub-objetos apagados
UPDATE public.documents d
SET data = jsonb_deep_merge(b.data, d.data),
    updated_at = now()
FROM backup_restore.documents b
WHERE d.collection = 'motoristas'
  AND b.collection = 'motoristas'
  AND d.id = b.id
  AND jsonb_deep_merge(b.data, d.data) IS DISTINCT FROM d.data;

-- RESTORE veiculos.extras: idem
UPDATE public.veiculos v
SET extras = jsonb_deep_merge(b.extras, COALESCE(v.extras, '{}'::jsonb)),
    updated_at = now()
FROM backup_restore.veiculos b
WHERE v.placa = b.placa
  AND b.extras IS NOT NULL AND b.extras <> '{}'::jsonb
  AND jsonb_deep_merge(b.extras, COALESCE(v.extras, '{}'::jsonb)) IS DISTINCT FROM COALESCE(v.extras, '{}'::jsonb);

\echo '=== DEPOIS ==='
SELECT 'motoristas_com_docs' AS k, count(*) AS v FROM public.documents WHERE collection='motoristas' AND jsonb_typeof(data->'documentos')='object' AND data->'documentos' <> '{}'::jsonb;
SELECT 'veiculos_com_extras' AS k, count(*) AS v FROM public.veiculos WHERE extras IS NOT NULL AND extras <> '{}'::jsonb;

DROP SCHEMA backup_restore CASCADE;

COMMIT;
